import assert from 'node:assert/strict'
import { mkdtempSync, readFileSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { chromium } from '/home/ian/.local/share/mise/installs/npm-playwright/1.63.0/node_modules/playwright/index.js'
import { createServer } from '/home/ian/hello-world/server.js'
import { createFileStore } from '/home/ian/hello-world/store.js'

const dir = mkdtempSync(join(tmpdir(), 'hello-load-race-'))
const dataFile = join(dir, 'hello.json')
const server = createServer(createFileStore(dataFile))
await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve))
const base = `http://127.0.0.1:${server.address().port}`
const browser = await chromium.launch({ headless: true })
const page = await browser.newPage()
const diagnostics = []
page.on('console', (message) => {
  if (message.type() === 'error' || message.type() === 'warning') diagnostics.push(`${message.type()}: ${message.text()}`)
})
page.on('pageerror', (error) => diagnostics.push(`pageerror: ${error.message}`))

let resolveInitialRequest
const initialRequest = new Promise((resolve) => { resolveInitialRequest = resolve })
let heldRoute
await page.route('**/api/text', async (route) => {
  if (!heldRoute && route.request().method() === 'GET') {
    heldRoute = route
    resolveInitialRequest()
    return
  }
  await route.continue()
})

try {
  const navigation = page.goto(base)
  await initialRequest
  const headline = page.locator('#text')
  await headline.click()
  await page.keyboard.press('Control+A')
  await page.keyboard.type('typed before load')

  await heldRoute.fulfill({
    status: 200,
    contentType: 'application/json; charset=utf-8',
    body: JSON.stringify({ text: 'stale server text' }),
  })
  await navigation

  assert.equal(await headline.textContent(), 'typed before load')
  await page.locator('#status').getByText(/^Saved /).waitFor({ timeout: 2000 })
  assert.equal(readFileSync(dataFile, 'utf8'), 'typed before load')
  assert.deepEqual(diagnostics, [])
  console.log('PASS: edit made during delayed initial GET remained visible and was persisted')
  console.log(`data: ${readFileSync(dataFile, 'utf8')}`)
  console.log('browser diagnostics: []')
} finally {
  await browser.close()
  await new Promise((resolve, reject) => server.close((error) => error ? reject(error) : resolve()))
  rmSync(dir, { recursive: true, force: true })
}

